  let zSample = textureSampleGrad(metallicRoughnessTexture, metallicRoughnessSampler, triplanarUVZ(p, normal), mipDx(triplanarDxZ(dpdxP, normal)), mipDy(triplanarDxZ(dpdyP, normal)));
