  let coc = circleOfConfusion(depth);
  let radiusPixels = coc * params.radius;
  let blurred = sampleBlurred(input.uv, radiusPixels);
  let mixAmount = clamp((radiusPixels / max(params.radius, 0.0001)) * params.intensity, 0.0, 1.0);
